// 上位半分にガード2桁を加え、B^(2m)/xの下側・誤差2未満の逆数を求める。
inline BigInt BigInt::reciprocalAbs(const BigInt& x){Int m=x.digits_.size();if(m<=32)return divmodSchoolbook(basePower(2*m),x).quotient;Int half=(m+1)/2+2,low=m-half;auto inverse=reciprocalAbs(shiftRight(x,low));auto product=x*(inverse*inverse);auto correction=shiftRight(product,2*half);for(Int i=0;i<std::min(2*half,Int(product.digits_.size()));++i)if(product.digits_[i]){correction+=1;break;}return shiftLeft(mulAbsSmall(inverse,2),low)-correction;}
inline BigIntDivision BigInt::correctDivisionProduct(const BigInt& x,const BigInt& y,BigInt quotient,const BigInt& product){BigIntDivision out{std::move(quotient),x-product};if(out.remainder.sign_<0){out.quotient-=1;out.remainder+=y;}for(int i=0;i<3;++i){if(cmpAbs(out.remainder,y)<0)break;out.quotient+=1;out.remainder-=y;}return out;}
// 長い被除数を除数長のブロックに分け、逆数と固定側NTTを再利用する。
