inline BigIntDivision BigInt::divmodNewton(const BigInt& x,const BigInt& y){auto dividend=x.abs(),divisor=y.abs();Int n=dividend.digits_.size(),m=divisor.digits_.size();BigIntDivision out;if(n>2*m)out=divmodBlocks(dividend,divisor);else{Int cut=std::max(Int(0),m-(n-m+2));auto high=shiftRight(divisor,cut);Int precision=std::max(m-cut,n-m);auto inverse=reciprocalAbs(shiftLeft(high,precision-(m-cut)));auto quotient=quotientFromReciprocal(shiftRight(dividend,cut),inverse,m-cut,precision);out=correctDivisionProduct(dividend,divisor,quotient,quotient*divisor);}out.quotient.sign_*=x.sign_*y.sign_;out.remainder.sign_*=x.sign_;return out;}
inline BigIntDivision BigInt::divmodTrunc(const BigInt& x,const BigInt& y){Int n=x.digits_.size(),m=y.digits_.size();if(std::min(m,n-m)>NewtonThreshold){Int size=n>2*m?2*m+8:std::max(n+1,2*std::min(m,n-m+2)+8);if(size<=(NttMaxLength*5)/9)return divmodNewton(x,y);}return divmodSchoolbook(x,y);}
